import{_ as o,o as n,c as a,a3 as r}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Your account","description":"","frontmatter":{},"headers":[],"relativePath":"use/account.md","filePath":"use/account.md"}'),t={name:"use/account.md"};function s(i,e,c,d,h,u){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="your-account" tabindex="-1">Your account <a class="header-anchor" href="#your-account" aria-label="Permalink to &quot;Your account&quot;">​</a></h1><p>You create your account in the web app, with your name, email and a password, or with a sign-in provider; see <a href="/wake-dist/docs/start/first-project#create-your-account">Your first project</a>. <strong>Account</strong>, the round button with your initial in the header, shows how you sign in, changes your password and signs you out everywhere.</p><h2 id="sign-in-with-a-provider" tabindex="-1">Sign in with a provider <a class="header-anchor" href="#sign-in-with-a-provider" aria-label="Permalink to &quot;Sign in with a provider&quot;">​</a></h2><p>When the server has sign-in providers turned on, the sign-in and sign-up screens show one button for each above the form: <strong>GitHub</strong>, <strong>Google</strong>, <strong>Microsoft</strong>, or the name your company gave its OpenID Connect provider, such as <strong>Acme SSO</strong>. Whoever runs the server turns them on (<a href="/wake-dist/docs/run/sign-in-providers">Sign-in providers</a>); a server without them offers email and password only.</p><p>The first sign-in with a provider account creates your user and personal workspace, as long as the provider reports your email as verified. Wake never joins a provider account to an existing user by email: if your email already has a Wake account, the screen says so. Sign in the way you already do, then link the provider from <strong>Account</strong>.</p><h2 id="sign-in-methods" tabindex="-1">Sign-in methods <a class="header-anchor" href="#sign-in-methods" aria-label="Permalink to &quot;Sign-in methods&quot;">​</a></h2><p><strong>Account</strong> lists how you can sign in: your password, if you have one, and each linked provider with the date you linked it.</p><ul><li><strong>Connect</strong> next to a provider takes you to it and links the account you choose there. Each provider account belongs to one Wake user, and you can link one account per provider; otherwise the screen says why.</li><li><strong>Disconnect</strong> unlinks a provider after you confirm. Wake keeps your last way to sign in: without a password, the last linked provider cannot be disconnected.</li></ul><h2 id="change-your-password" tabindex="-1">Change your password <a class="header-anchor" href="#change-your-password" aria-label="Permalink to &quot;Change your password&quot;">​</a></h2><p>Under <strong>Change password</strong>, enter your current password and a new one of 12 to 128 characters. It signs out your other browsers and keeps this one signed in; your personal access tokens and connected agents keep working.</p><p>A wrong current password is refused, and those attempts count with sign-ins: after 10 in a minute from one address, the next one waits. An account that signs in only with a provider has no password to change.</p><h2 id="sign-out-everywhere" tabindex="-1">Sign out everywhere <a class="header-anchor" href="#sign-out-everywhere" aria-label="Permalink to &quot;Sign out everywhere&quot;">​</a></h2><p>Use it when a device or a token may be in someone else&#39;s hands. <strong>Sign out everywhere</strong>, after a confirmation, revokes everything that acts as you, in every workspace and in one step:</p><ul><li>every browser session, this one included;</li><li>every personal access token, the CLI&#39;s too;</li><li>every connected agent, with its access and refresh tokens and any consent not redeemed yet;</li><li>every <code>wake login</code> or <code>wake setup</code> you approved that the CLI has not picked up yet.</li></ul><p>Afterwards, sign in again, run <code>wake login</code> on each computer and sign each agent in again, as in <a href="/wake-dist/docs/start/first-project#sign-your-agent-in">Sign your agent in</a>. The repository&#39;s files need no change. Each revoked token gets a <code>token.revoked</code> entry in its workspace&#39;s <a href="/wake-dist/docs/use/audit-log">audit log</a> with the cause <code>signed_out_everywhere</code>.</p><h2 id="browsers-and-accounts" tabindex="-1">Browsers and accounts <a class="header-anchor" href="#browsers-and-accounts" aria-label="Permalink to &quot;Browsers and accounts&quot;">​</a></h2><p>Each account stays signed in on at most 3 browsers; signing in on a fourth signs out the one that signed in longest ago. An account is for one person: see <a href="/wake-dist/docs/run/sign-up">Sign-up and accounts</a>.</p>',17)])])}const l=o(t,[["render",s]]);export{p as __pageData,l as default};
